with session_totals as (select session_id, sum(duration_sec) as total_duration_sec, avg(duration_sec) as avg_duration_sec from web_events where event_type = 'click' group by session_id) select sessions.id, sessions.started_at, sessions.country, session_totals.total_duration_sec, session_totals.avg_duration_sec from sessions inner join session_totals on sessions.id = session_totals.session_id where session_totals.avg_duration_sec > 180;
